#!/bin/bash
cd "$(dirname "$0")"
{
cat <<'H'
<title>TURVIO Driver</title>
<meta name="claude:viewport-fit-sides" content="cover">
<meta name="theme-color" content="#090B11">
<link rel="icon" type="image/png" href="data:image/png;base64,">
<link rel="apple-touch-icon" href="data:image/png;base64,">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap">
<style>
H
cat ../brand/brand.css base.css mapstyle.css dispatch.css driver.css
cat <<'H'
</style>
<div class="stage">
  <div class="stage-bar" id="stagebar"></div>
  <div class="device" id="device">
    <div class="sbar" aria-hidden="true"><span id="sbar-clock">11:42</span><span class="isl"></span><span class="sbar-r"><span id="sbar-net" style="display:flex;gap:4px"></span><svg width="22" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="2" y="7" width="18" height="10" rx="2"/><path d="M22 11v2M5 10h11v4H5z" fill="currentColor"/></svg></span></div>
    <div class="view-area" id="view"></div>
    <nav class="tabbar" id="tabbar" aria-label="TURVIO"></nav>
    <div class="toastx" id="toastx" aria-live="polite"></div>
    <div class="layer" id="layer"></div>
    <div class="msheet" id="msheet" role="dialog" aria-modal="true"></div>
    <div class="full" id="full" role="dialog" aria-modal="true"></div>
    <div class="navh" id="navh" role="dialog" aria-modal="true"></div>
    <div class="done-ov" id="doneov" aria-live="assertive"></div>
    <div class="splash" id="splash" role="img" aria-label="TURVIO"><span class="logo-mark splash-mark"></span></div>
  </div>
</div>
<script>
H
cat brandicon.js map.js data.js i18n.js app.js
echo '</script>'
} > index.html
(echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><style>[hidden]{display:none!important}body{margin:0}</style></head><body>'; cat index.html; echo '</body></html>') > preview.html
